cards=[]
for n,(title,cat,vid,start,end,level,fact,prompt,choices) in enumerate(rows,1):
    item=inv[vid]
    options=choices.split('|')
    cards.append(dict(id=f'RK-{n:03}',title=title,category=cat,evidence=level,date=item['broadcast_date_from_title'],source_url=item['url']+(f'&t={start}s' if start is not None else ''),start_seconds=start,end_seconds=end,source_fact=fact,verification_needed='원음·화면과 발화자 확인'+(' 및 콘텐츠 구간 탐색' if level=='C' else ''),game_prompt=prompt,choices=[dict(text=x,outcome='미정: 실제 결과를 뜻하지 않는 게임 설계 항목') for x in options],eligibility='초안: 플레이테스트 전',chain=('RK-020→RK-021: 하나의 보스 도전에서 이어지는 연속 카드' if n in (20,21) else None)))
(OUT/'rakoko_event_cards.json').write_text(json.dumps(dict(version='0.1',as_of='2026-11-03',cards=cards),ensure_ascii=False,indent=2),encoding='utf-8')
counts=Counter(c['evidence'] for c in cards)
lines=['# 라코코의 방송일지 — 가벼운 사건 카드 v0.1','',f'작성: 2026-11-03 | {len(cards)}개 카드 / {len(cards)-1}개 소재 묶음 | B {counts["B"]}개 · C {counts["C"]}개 · A 0개','',
'## 읽는 법','',
'- B: 확보한 자동자막의 해당 구간을 읽은 초안. 원음·화면·발화자까지 검증한 사실은 아니다.','- C: 다시보기 목록의 제목을 바탕으로 만든 후보. 실제 방송 내용과 반응은 검증 전이다.','- 사실 기록과 게임 문장은 별개다. 아래 상황·선택지는 창작이며 실제 발언이나 실제 선택의 재현이 아니다. 확률과 수치 효과는 아직 정하지 않았다.','- 건강·응급실, 계약 종료·분쟁, 사생활, 오컬트, 신체 평가와 성적 벌칙은 카드 소재에서 제외했다.','- YouTube 추가 요청 없이 기존 로컬 자막과 목록으로 작성했다. 외부 검색에서 발견한 사건을 다시보기로 검증 완료했다는 뜻은 아니다.','- RK-020과 RK-021은 같은 도전의 연속 카드다. 독립 사건 수를 늘리기 위해 중복 계산하지 않는다.','',
'## 우선 제작 후보','',
'첫 방송 설정 실수 → AI 사진 감별 → 테란 첫 도전 → 콘텐츠 회의 → 생일 축하 → 트리가드 도전의 순서가 좋다. 준비·게임·팬 소통을 섞고, 장비 오류 카드는 낮은 빈도로 넣는다. 실패해도 중대한 손해 대신 방송 시간이나 준비 일정이 조금 바뀌는 방향으로 설계한다.','',
'## 카드 목록','']
for c in cards:
    stamp='구간 미지정' if c['start_seconds'] is None else f'{c["start_seconds"]}–{c["end_seconds"]}초'
    lines += [f'### {c["id"]} · {c["title"]}', '',f'- 분류: {c["category"]} | 근거 {c["evidence"]} | {c["date"]}',f'- 출처: [다시보기 · {stamp}]({c["source_url"]})',f'- 확인한 내용: {c["source_fact"]}',f'- 추가 확인: {c["verification_needed"]}',f'- 게임 상황〔각색〕: {c["game_prompt"]}',f'- 선택지〔각색〕: '+ ' / '.join(x['text'] for x in c['choices']),'- 결과: 미정. 자막으로 실제 결과나 수치 효과를 추정하지 않는다.']
    if c['chain']: lines += [f'- 연결: {c["chain"]}']
    lines += ['']
lines += ['## 다음 검증 순서','', '1. 우선 제작 후보의 원음·화면을 확인해 발화자, 설정 실수, 실제 게임 흐름을 확정한다.','2. C 후보는 실제 콘텐츠 구간을 찾은 후 유지·수정·삭제한다.','3. 외부 검색 후보는 게시 날짜와 원출처를 확보한 뒤 다시보기와 대조한다. 카페 점검·영상 예약 공개 같은 이야기는 아직 사실 카드에 넣지 않았다.','4. 원문 대사 복사 대신 말투 가이드를 사용해 짧은 창작 대사를 작성한다.']
(OUT/'rakoko_event_cards.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
assert len(cards)==24 and counts=={'B':21,'C':3}
assert all(c['id']==f'RK-{i:03}' for i,c in enumerate(cards,1))
assert all(c['start_seconds'] is None or 0<=c['start_seconds']<c['end_seconds']<=inv[rows[i][2]]['duration'] for i,c in enumerate(cards))
print(f'Validated {len(cards)} cards, 23 source clusters; {dict(counts)}; timestamps within video durations.')
